verus! {
    #[verifier::spec]
    fn meshgrid(x: Vec<f32>, y: Vec<f32>) -> (result: (Vec<Vec<f32>>, Vec<Vec<f32>>)) {
        // Precondition: both input arrays must be non-empty
        requires(!x.is_empty() && !y.is_empty());
        
        // The lengths of the input arrays
        let n = x.len();
        let m = y.len();
        
        // Initialize the output matrices
        let mut grid_x: Vec<Vec<f32>> = Vec::with_capacity(m);
        let mut grid_y: Vec<Vec<f32>> = Vec::with_capacity(m);
        
        // Invariant: grid_x and grid_y should have m rows and n columns
        // and should be filled correctly
        invariant {
            grid_x.len() == grid_y.len() && grid_x.len() <= m && grid_y.len() <= m;
            forall(|i: usize| {
                (i < grid_x.len() ==> grid_x[i].len() == n) &&
                (i < grid_y.len() ==> grid_y[i].len() == n)
            })
        }
        
        // Fill the output matrices
        for i in 0..m {
            // Ensure we do not exceed the bounds of y
            assert!(i < y.len());
            
            // Create a new row for grid_x and grid_y
            let mut row_x: Vec<f32> = Vec::with_capacity(n);
            let mut row_y: Vec<f32> = Vec::with_capacity(n);
            
            for j in 0..n {
                // Ensure we do not exceed the bounds of x
                assert!(j < x.len());
                
                // Fill the rows according to the meshgrid definition
                row_x.push(x[j]);
                row_y.push(y[i]);
            }
            
            // Add the filled rows to the output matrices
            grid_x.push(row_x);
            grid_y.push(row_y);
        }
        
        // Postcondition: the output matrices should have the correct dimensions
        ensures(grid_x.len() == m && grid_y.len() == m);
        ensures(forall(|i: usize| {
            (i < m ==> grid_x[i].len() == n) &&
            (i < m ==> grid_y[i].len() == n)
        }));
        
        (grid_x, grid_y)
    }
}